function f = HS65_f(x)
f = (x(1) - x(2)).^2 + (x(3) - 5).^2 + (x(1) + x(2) - 10).^2/9;
end

function g = HS65_g(x)
g = zeros(3, 1);
g(1) = 20*x(1)/9 - 16*x(2)/9 - 20/9;
g(2) = -16*x(1)/9 + 20*x(2)/9 - 20/9;
g(3) = 2*x(3) - 10;
end

function c = HS65_c(x)
